export default {
	props: {
		// 是否显示返回按钮
		isShowBack: {
			type: Boolean,
			required: false,
			default: true
		},
		// 背景色
		bgImage: {
			type: String,
			required: false,
			default: ''
		}
	},
	data() {
		return {
			customeBar: this.$customeBar
		};
	},

	computed: {
		style() {
			let customeBar = this.$customeBar,
				bgImage = this.bgImage;

			let style = `height:${customeBar}px;`;

			if (this.bgImage) {
				style = `${style}background-image:${bgImage};`;
			}
			return style;
		}
	},

	methods: {
		// 点击返回
		backPage() {
			var pages = getCurrentPages();

			// 当不存在上级页面
			if (pages.length === 1) {
				const isFamily = this.$store.state.userInfo.familyId;
				if (isFamily) {
					uni.switchTab({
						url: '/pages/index/index'
					});
				} else {
					uni.redirectTo({ url: '/pages/family/index' });
				}

				return;
			}
			uni.navigateBack({
				delta: 1
			});
		}
	}
};
